import type Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';

/**
 * Applies pending `migration.sql` files in order, tracked in `schema_migrations`.
 * Migration SQL is generated by `prisma migrate dev` (single source of truth);
 * this runner only *applies* it so packaged apps migrate without the schema engine.
 */
export function resolveMigrationsDir(): string | undefined {
  const candidates = [
    path.join(__dirname, '..', 'prisma', 'migrations'), // dist/prisma/migrations (copied at build)
    path.join(__dirname, '..', '..', 'prisma', 'migrations'), // tsx dev (src/db -> backend root)
    path.join(process.cwd(), 'prisma', 'migrations'), // CLI cwd fallback
  ];
  const resourcesPath = (process as NodeJS.Process & { resourcesPath?: string }).resourcesPath;
  if (typeof resourcesPath === 'string') {
    candidates.unshift(path.join(resourcesPath, 'backend', 'prisma', 'migrations'));
  }
  return candidates.find((d) => fs.existsSync(d));
}

export function applyPendingMigrations(db: Database.Database, dir: string): string[] {
  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)`);
  const applied = new Set(
    (db.prepare(`SELECT name FROM schema_migrations`).all() as { name: string }[]).map((r) => r.name),
  );
  const pending = fs
    .readdirSync(dir)
    .filter((d) => {
      try {
        return fs.statSync(path.join(dir, d)).isDirectory() && !applied.has(d);
      } catch {
        return false;
      }
    })
    .sort();
  const insert = db.prepare(`INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)`);
  for (const name of pending) {
    const sql = fs.readFileSync(path.join(dir, name, 'migration.sql'), 'utf8');
    db.transaction(() => {
      db.exec(sql);
      insert.run(name, new Date().toISOString());
    })();
  }
  return pending;
}
